<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Copy, ImagePlus, Package, Pencil, Plus, Save, Search, Trash2, X } from '@lucide/vue'
import AttributeValueField, { type AttributeDraftValue } from '../components/AttributeValueField.vue'
import BaseCheckbox from '../components/BaseCheckbox.vue'
import BaseDialog from '../components/BaseDialog.vue'
import BaseInput from '../components/BaseInput.vue'
import BaseSelect from '../components/BaseSelect.vue'
import BaseTextarea from '../components/BaseTextarea.vue'
import EditorSteps from '../components/EditorSteps.vue'
import PaginationControls from '../components/PaginationControls.vue'
import { usePaginatedCollection } from '../composables/usePaginatedCollection'
import type { Attribute } from '../services/attributes'
import { getAllBrands, type Brand } from '../services/brands'
import { getCategories, type Category } from '../services/categories'
import { getCategoryAttributes, getProductAttributeValues, saveProductAttributeValues } from '../services/productAttributes'
import { deleteProductGroup, getAllProductGroups, ProductGroupRequestError, saveProductGroup, type ProductGroup, type ProductGroupPayload } from '../services/productGroups'
import { deleteProductImage, getAllProductImages, updateProductImage, uploadProductImage, type ProductImage } from '../services/productImages'
import { getProductRelations, getRelationCandidates, ProductRelationRequestError, saveProductRelations, type ProductRelationType } from '../services/productRelations'
import { deleteProduct, getProducts, saveProduct, type Product, type ProductFilters, type ProductPayload, type ProductUnit } from '../services/products'
import { useAuthStore } from '../stores/auth'

type Step = 'main' | 'attributes' | 'images' | 'group' | 'review'
type RelationForm = { related_product_id: string; type: ProductRelationType; sort_order: string }
const auth = useAuthStore(); const list = usePaginatedCollection<Product>('Не удалось загрузить товары.')
const { items: products, pagination, error, loading } = list
const categories = ref<Category[]>([]); const brands = ref<Brand[]>([]); const candidates = ref<Product[]>([]); const groupProducts = ref<ProductGroup['products']>([])
const opened = ref(false); const saving = ref(false); const editing = ref<Product | null>(null); const deleting = ref<Product | null>(null); const activeStep = ref<Step>('main'); const success = ref('')
const confirmError = ref('')
const filters = ref({ search: '', category_id: '', brand_id: '', is_active: '', has_stock: '', price_from: '', price_to: '' })
const form = ref<ProductPayload>(emptyProduct()); const manuallyEditedSlug = ref(false); const copiedFromProduct = ref<Product | null>(null); const copiedNameError = ref('')
const attributes = ref<Attribute[]>([]); const attributeValues = ref<Record<number, AttributeDraftValue>>({}); const requiredIds = ref<number[]>([])
const images = ref<ProductImage[]>([]); const selectedFile = ref<File | null>(null); const imageInput = ref<HTMLInputElement | null>(null); const imageDeleting = ref<ProductImage|null>(null); const imageStatus = ref('')
const groups = ref<ProductGroup[]>([]); const selectedGroupId = ref(''); const groupErrors = ref<Record<string, string[]>>({}); const groupForm = ref<ProductGroupPayload>({ name: '', code: '', axis_attribute_ids: [], product_ids: [] }); const groupSearch=ref(''); const groupDeleting=ref(false)
const relations = ref<RelationForm[]>([]); const relationErrors = ref<Record<number, string>>({}); const relationSearch=ref('')
const canManage = computed(() => auth.hasPermission('catalog.manage'))
const copiedFromName = computed(() => copiedFromProduct.value?.name ?? null)
const steps = [{ id: 'main', label: 'Основное и продажа' }, { id: 'attributes', label: 'Характеристики' }, { id: 'images', label: 'Фото' }, { id: 'group', label: 'Варианты модели' }, { id: 'review', label: 'Проверка' }]
const units: Array<{ value: ProductUnit; label: string }> = [{ value:'piece',label:'Штука'},{value:'square_meter',label:'Квадратный метр'},{value:'linear_meter',label:'Погонный метр'},{value:'package',label:'Упаковка'},{value:'kilogram',label:'Килограмм'},{value:'liter',label:'Литр'},{value:'set',label:'Комплект'}]
const relationTypes = [{ value: 'related', label: 'Сопутствующий товар' }, { value: 'recommended', label: 'Рекомендуемый товар' }]
const stateOptions=[{value:'',label:'Любая активность'},{value:'1',label:'Активные'},{value:'0',label:'Черновики'}];const stockOptions=[{value:'',label:'Любой остаток'},{value:'1',label:'В наличии'},{value:'0',label:'Нет в наличии'}]
function flatten(nodes: Category[], depth=0): Array<Category & {depth:number}> { return nodes.flatMap(item => [{...item,depth},...flatten(item.children??[],depth+1)]) }
const categoryOptions = computed(() => flatten(categories.value).filter(item=>item.is_active).map(item=>({value:String(item.id),label:`${'— '.repeat(item.depth)}${item.name}`})))
const brandOptions = computed(() => [{value:'',label:'Без бренда'},...brands.value.map(item=>({value:String(item.id),label:item.name}))]); const filterCategoryOptions=computed(()=>[{value:'',label:'Все категории'},...categoryOptions.value]); const filterBrandOptions=computed(()=>[{value:'',label:'Все бренды'},...brandOptions.value.slice(1)])
const selectedCategory=computed({get:()=>form.value.category_id?String(form.value.category_id):'',set:value=>form.value.category_id=Number(value)}); const selectedBrand=computed({get:()=>form.value.brand_id===null?'':String(form.value.brand_id),set:value=>form.value.brand_id=value?Number(value):null})
const groupOptions=computed(()=>[{value:'',label:'Новая группа'},...groups.value.map(group=>({value:String(group.id),label:`${group.name} · ${group.code}`}))]); const currentGroup=computed(()=>groups.value.find(group=>group.products.some(product=>product.id===editing.value?.id))??null)
const selectableCandidates=computed(()=>candidates.value.filter(product=>!relations.value.some(row=>Number(row.related_product_id)===product.id)).map(product=>({value:String(product.id),label:`${product.name} · ${product.sku}`})))
const translit:Record<string,string>={а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'yo',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'shch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'}
function slugify(value:string){return Array.from(value.toLowerCase(),c=>translit[c]??c).join('').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')}
function normalizedName(value:string){return value.trim().replace(/\s+/g,' ').toLocaleLowerCase('ru-RU')}
function emptyProduct():ProductPayload{return{category_id:0,brand_id:null,name:'',slug:'',description:'',sku:'',article_number:null,barcode:null,unit:'piece',price:'0.00',old_price:null,stock_quantity:0,is_active:false}}
function toPayload(p:Product):ProductPayload{return{category_id:p.category_id,brand_id:p.brand_id,name:p.name,slug:p.slug,description:p.description??'',sku:p.sku,article_number:p.article_number,barcode:p.barcode,unit:p.unit,price:p.price,old_price:p.old_price,stock_quantity:p.stock_quantity,is_active:p.is_active}}
function inputValue(v:unknown):AttributeDraftValue{if(Array.isArray(v))return v.map(String);if(typeof v==='boolean')return v?'true':'false';return String(v??'')}
function displayAttributeValue(attribute:Attribute|undefined,value:unknown):string{
  if(attribute?.type==='select')return attribute.options.find(option=>option.value===String(value))?.label??String(value??'')
  if(typeof value==='boolean')return value?'Да':'Нет'
  if(Array.isArray(value))return value.map(item=>String(item)).join(', ')
  return String(value??'')
}
function hasValue(v:AttributeDraftValue|undefined){return Array.isArray(v)?v.length>0:String(v??'').trim()!==''}
function typed(a:Attribute,v:AttributeDraftValue):string|number|boolean|string[]{if(a.type==='integer')return Number.parseInt(String(v),10);if(a.type==='decimal')return Number(v);if(a.type==='boolean')return v==='true';if(a.type==='multiselect')return Array.isArray(v)?v:[];return String(v)}
function enabled(step:string){return step==='main'||editing.value!==null}
function filtersPayload():ProductFilters{return{search:filters.value.search||undefined,category_id:filters.value.category_id?Number(filters.value.category_id):undefined,brand_id:filters.value.brand_id?Number(filters.value.brand_id):undefined,is_active:filters.value.is_active===''?undefined:filters.value.is_active==='1',has_stock:filters.value.has_stock===''?undefined:filters.value.has_stock==='1',price_from:filters.value.price_from||undefined,price_to:filters.value.price_to||undefined}}
async function fetchPage(page:number){const [productPage,categoryList,brandList]=await Promise.all([getProducts({...filtersPayload(),page}),getCategories(),getAllBrands()]);return{...productPage,categoryList,brandList}}
async function load(page=pagination.value?.current_page??1){const response=await list.load(page,fetchPage);if(response){categories.value=response.categoryList;brands.value=response.brandList}}
function resetFilters(){filters.value={search:'',category_id:'',brand_id:'',is_active:'',has_stock:'',price_from:'',price_to:''};void load(1)}
function fillGroup(group:ProductGroup|null,id:number){selectedGroupId.value=group?String(group.id):'';groupForm.value=group?{name:group.name,code:group.code,axis_attribute_ids:group.axes.map(a=>a.id),product_ids:group.products.map(p=>p.id)}:{name:'',code:'',axis_attribute_ids:[],product_ids:[id]}}
function prepareGroupDraft(product:Product,groupList:ProductGroup[]){
  const ownGroup=groupList.find(group=>group.products.some(item=>item.id===product.id))??null
  if(ownGroup){groupProducts.value=ownGroup.products;fillGroup(ownGroup,product.id);return}
  const source=copiedFromProduct.value
  const compatible=source&&source.category_id===product.category_id&&source.brand_id===product.brand_id
  if(!source||!compatible){groupProducts.value=[product];fillGroup(null,product.id);return}
  const sourceGroup=groupList.find(group=>group.products.some(item=>item.id===source.id))??null
  if(sourceGroup){groupProducts.value=[...sourceGroup.products,product];fillGroup(sourceGroup,product.id);groupForm.value.product_ids=[...groupForm.value.product_ids,product.id];return}
  groupProducts.value=[source,product];fillGroup(null,product.id);groupForm.value.product_ids=[source.id,product.id]
}
function copyAttributeDrafts(values:Record<number,AttributeDraftValue>){return Object.fromEntries(Object.entries(values).map(([id,value])=>[id,Array.isArray(value)?[...value]:value]))}
async function loadDetails(product:Product,copiedAttributes:Record<number,AttributeDraftValue>|null=null){const [categoryAttrs,savedAttrs,photoList,relationList,groupList,candidateList]=await Promise.all([getCategoryAttributes(product.category_id),getProductAttributeValues(product.id),getAllProductImages(product.id),getProductRelations(product.id),getAllProductGroups(),getRelationCandidates(product.id)])
  attributes.value=categoryAttrs;requiredIds.value=categoryAttrs.filter(a=>a.is_required).map(a=>a.id);const saved=new Map(savedAttrs.map(v=>[v.attribute_id,v.value]));attributeValues.value=Object.fromEntries(categoryAttrs.map(a=>[a.id,copiedAttributes&&a.id in copiedAttributes?copiedAttributes[a.id]:inputValue(saved.get(a.id))]));images.value=photoList;relations.value=relationList.map(r=>({related_product_id:String(r.related_product_id),type:r.type,sort_order:String(r.sort_order)}));groups.value=groupList;prepareGroupDraft(product,groupList);const related=relationList.map(relation=>relation.related_product);candidates.value=[...related,...candidateList.filter(item=>!related.some(savedProduct=>savedProduct.id===item.id))]}
async function open(product:Product|null=null){error.value='';success.value='';copiedFromProduct.value=null;copiedNameError.value='';editing.value=product;activeStep.value='main';form.value=product?toPayload(product):emptyProduct();manuallyEditedSlug.value=Boolean(product);opened.value=true;attributes.value=[];attributeValues.value={};images.value=[];relations.value=[];groups.value=[];groupProducts.value=[];selectedGroupId.value='';groupForm.value={name:'',code:'',axis_attribute_ids:[],product_ids:[]};groupErrors.value={};groupSearch.value='';if(product)try{await loadDetails(product)}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось загрузить карточку.'}}
async function cloneProduct(product:Product){await open(null);copiedFromProduct.value=product;form.value={...toPayload(product),name:'',slug:'',sku:'',article_number:null,barcode:null,is_active:false};manuallyEditedSlug.value=false;try{const [attrs,values]=await Promise.all([getCategoryAttributes(product.category_id),getProductAttributeValues(product.id)]);attributes.value=attrs;const saved=new Map(values.map(v=>[v.attribute_id,v.value]));attributeValues.value=Object.fromEntries(attrs.map(a=>[a.id,inputValue(saved.get(a.id))]));success.value='Данные и характеристики скопированы без фотографий. Укажите отличающееся название и новый SKU — URL сформируется из названия.'}catch{error.value='Основные данные скопированы, но характеристики исходного товара загрузить не удалось.'}}
function close(){if(!saving.value){opened.value=false;editing.value=null}}
async function saveMain(){if(saving.value)return;copiedNameError.value='';if(copiedFromProduct.value&&normalizedName(form.value.name)===normalizedName(copiedFromProduct.value.name)){copiedNameError.value=`Название должно отличаться от исходного товара «${copiedFromProduct.value.name}».`;return}const copiedAttributes=copiedFromProduct.value?copyAttributeDrafts(attributeValues.value):null;saving.value=true;error.value='';try{const saved=await saveProduct(editing.value?.id??null,{...form.value,is_active:editing.value?form.value.is_active:false,article_number:form.value.article_number||null,barcode:form.value.barcode||null,old_price:form.value.old_price||null});editing.value=saved;form.value=toPayload(saved);await load();await loadDetails(saved,copiedAttributes);success.value='Основные и коммерческие данные сохранены.';activeStep.value='attributes'}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось сохранить товар.'}finally{saving.value=false}}
async function saveAttributes(){if(!editing.value)return;saving.value=true;try{await saveProductAttributeValues(editing.value.id,{attributes:attributes.value.filter(a=>hasValue(attributeValues.value[a.id])).map(a=>({attribute_id:a.id,value:typed(a,attributeValues.value[a.id])}))});success.value='Характеристики сохранены.';activeStep.value='images'}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось сохранить характеристики.'}finally{saving.value=false}}
function selectFile(event:Event){selectedFile.value=(event.target as HTMLInputElement).files?.[0]??null}
function chooseFile(){imageInput.value?.click()}
async function upload(){if(!editing.value||!selectedFile.value||saving.value)return;saving.value=true;error.value='';try{const image=await uploadProductImage(editing.value.id,selectedFile.value,{sort_order:images.value.length});images.value.push(image);selectedFile.value=null;if(imageInput.value)imageInput.value.value='';success.value=`Фотография ${image.alt} загружена.`}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось загрузить фотографию.'}finally{saving.value=false}}
async function reorderImage(index:number,direction:-1|1){if(!editing.value)return;const target=index+direction;if(target<0||target>=images.value.length)return;const reordered=[...images.value];[reordered[index],reordered[target]]=[reordered[target],reordered[index]];saving.value=true;try{for(const [position,image] of reordered.entries())await updateProductImage(editing.value.id,image.id,{sort_order:position,is_primary:position===0});images.value=await getAllProductImages(editing.value.id);imageStatus.value=`Порядок сохранён. Изображение на позиции ${target+1}.`}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось изменить порядок.'}finally{saving.value=false}}
async function removeImage(){if(!editing.value||!imageDeleting.value||saving.value)return;saving.value=true;confirmError.value='';try{await deleteProductImage(editing.value.id,imageDeleting.value.id);imageDeleting.value=null;images.value=await getAllProductImages(editing.value.id)}catch(reason){confirmError.value=reason instanceof Error?reason.message:'Не удалось удалить фотографию.'}finally{saving.value=false}}
function selectGroup(id:string){fillGroup(groups.value.find(g=>String(g.id)===id)??null,editing.value!.id)}
async function searchGroupProducts(){if(!editing.value||saving.value)return;saving.value=true;error.value='';try{const found=(await getProducts({search:groupSearch.value||undefined,category_id:editing.value.category_id,brand_id:editing.value.brand_id??undefined,page:1,perPage:25})).data;const selected=groupProducts.value.filter(product=>groupForm.value.product_ids.includes(product.id));groupProducts.value=[...selected,...found.filter(product=>!selected.some(item=>item.id===product.id))]}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось найти товары.'}finally{saving.value=false}}
async function saveGroup(){if(!editing.value||saving.value)return;groupErrors.value={};if(!groupForm.value.axis_attribute_ids.length){groupErrors.value.axis_attribute_ids=['Выберите хотя бы одну характеристику.'];return}if(groupForm.value.product_ids.length<2){groupErrors.value.product_ids=['Добавьте минимум два товара.'];return}saving.value=true;try{const saved=await saveProductGroup(selectedGroupId.value?Number(selectedGroupId.value):null,groupForm.value);groups.value=await getAllProductGroups();fillGroup(saved,editing.value.id);copiedFromProduct.value=null;success.value='Группа вариантов сохранена.';activeStep.value='review'}catch(reason){if(reason instanceof ProductGroupRequestError)groupErrors.value=reason.details;error.value=reason instanceof Error?reason.message:'Не удалось сохранить группу.'}finally{saving.value=false}}
function addRelation(){const id=selectableCandidates.value[0]?.value;if(id)relations.value.push({related_product_id:id,type:'related',sort_order:String(relations.value.length)})}
async function searchRelations(){if(!editing.value||saving.value)return;saving.value=true;error.value='';try{const found=await getRelationCandidates(editing.value.id,relationSearch.value,20);const selected=candidates.value.filter(product=>relations.value.some(row=>Number(row.related_product_id)===product.id));candidates.value=[...selected,...found.filter(product=>!selected.some(item=>item.id===product.id))]}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось найти товары.'}finally{saving.value=false}}
async function saveRelations(){if(!editing.value||saving.value)return;relationErrors.value={};saving.value=true;try{const saved=await saveProductRelations(editing.value.id,{relations:relations.value.map(r=>({related_product_id:Number(r.related_product_id),type:r.type,sort_order:Number(r.sort_order)}))});relations.value=saved.map(r=>({related_product_id:String(r.related_product_id),type:r.type,sort_order:String(r.sort_order)}));success.value='Рекомендации сохранены.'}catch(reason){if(reason instanceof ProductRelationRequestError)Object.entries(reason.details).forEach(([key,messages])=>{const m=key.match(/^relations\.(\d+)/);if(m)relationErrors.value[Number(m[1])]=messages[0]});error.value=reason instanceof Error?reason.message:'Не удалось сохранить рекомендации.'}finally{saving.value=false}}
async function removeProduct(){if(!deleting.value||saving.value)return;saving.value=true;confirmError.value='';try{await deleteProduct(deleting.value.id);deleting.value=null;await load()}catch(reason){confirmError.value=reason instanceof Error?reason.message:'Не удалось удалить товар.'}finally{saving.value=false}}
async function ungroup(){if(!selectedGroupId.value||saving.value)return;saving.value=true;confirmError.value='';try{await deleteProductGroup(Number(selectedGroupId.value));groups.value=await getAllProductGroups();fillGroup(null,editing.value!.id);groupDeleting.value=false;success.value='Группа удалена.'}catch(reason){confirmError.value=reason instanceof Error?reason.message:'Не удалось удалить группу.'}finally{saving.value=false}}
async function publish(){if(!editing.value)return;saving.value=true;error.value='';try{const saved=await saveProduct(editing.value.id,{...form.value,is_active:true});editing.value=saved;form.value=toPayload(saved);success.value='Товар опубликован.';await load()}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось опубликовать товар.'}finally{saving.value=false}}
onMounted(load)
</script>

<template>
<section class="mx-auto admin-page" :aria-busy="loading"><div class="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-medium text-gray-500">Каталог</p><h1 class="mt-1 text-2xl font-bold text-gray-900 sm:text-3xl">Товары</h1><p class="mt-2 text-sm text-gray-500">Каждая карточка — отдельная продаваемая позиция со своими фото.</p></div><button v-if="canManage" class="inline-flex items-center gap-2 rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white" @click="open()"><Plus :size="18"/>Добавить товар</button></div>
<p v-if="loading" class="sr-only" role="status">Загрузка товаров…</p>
<p v-if="error&&!opened" class="mb-4 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-500" role="alert">{{error}}</p>
<form class="rounded-xl border border-gray-200 bg-white p-5 shadow-card" @submit.prevent="load(1)"><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><label class="text-sm font-medium text-gray-700 xl:col-span-2">Поиск<BaseInput v-model="filters.search" class="mt-1.5" searchable placeholder="Название, SKU, артикул"/></label><label class="text-sm font-medium text-gray-700">Категория<BaseSelect v-model="filters.category_id" class="mt-1.5" :options="filterCategoryOptions" accessible-name="Категория" searchable/></label><label class="text-sm font-medium text-gray-700">Бренд<BaseSelect v-model="filters.brand_id" class="mt-1.5" :options="filterBrandOptions" accessible-name="Бренд" searchable/></label><label class="text-sm font-medium text-gray-700">Активность<BaseSelect v-model="filters.is_active" class="mt-1.5" :options="stateOptions" accessible-name="Активность"/></label><label class="text-sm font-medium text-gray-700">Остаток<BaseSelect v-model="filters.has_stock" class="mt-1.5" :options="stockOptions" accessible-name="Остаток"/></label><label class="text-sm font-medium text-gray-700">Цена от<BaseInput v-model="filters.price_from" class="mt-1.5" type="number" min="0" step="0.01"/></label><label class="text-sm font-medium text-gray-700">Цена до<BaseInput v-model="filters.price_to" class="mt-1.5" type="number" min="0" step="0.01"/></label></div><div class="mt-4 flex gap-2"><button class="inline-flex items-center gap-2 rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white"><Search :size="17"/>Найти</button><button type="button" class="px-4 py-2 text-sm font-semibold text-gray-600" @click="resetFilters">Сбросить</button></div></form>
<div class="mt-6 overflow-hidden rounded-xl border border-gray-200 bg-white shadow-card">
  <article v-for="product in products" :key="product.id" class="flex flex-wrap items-center gap-4 border-b border-gray-100 p-4">
    <img v-if="product.primary_image" :src="product.primary_image.url" :alt="product.primary_image.alt||product.name" class="h-12 w-12 rounded-lg object-cover"><span v-else class="grid h-12 w-12 place-items-center rounded-lg bg-primary-50 text-primary-600"><Package :size="20"/></span>
    <div class="min-w-0 flex-1"><div class="flex flex-wrap gap-2"><h2 class="font-semibold text-gray-800">{{product.name}}</h2><span class="rounded-full px-2 py-1 text-xs" :class="product.is_active?'bg-success-50 text-success-500':'bg-gray-100 text-gray-500'">{{product.is_active?'Активен':'Черновик'}}</span></div><p class="mt-1 text-sm text-gray-500">{{product.sku}} · {{product.price}} ₽ · Остаток: {{product.stock_quantity}}</p></div>
    <button :aria-label="`Создать похожий товар ${product.name}`" class="rounded-lg p-2 text-gray-500 hover:bg-primary-50" @click="cloneProduct(product)"><Copy :size="17"/></button><button :aria-label="`Редактировать товар ${product.name}`" class="rounded-lg p-2 text-primary-600 hover:bg-primary-50" @click="open(product)"><Pencil :size="17"/></button><button :aria-label="`Удалить товар ${product.name}`" class="rounded-lg p-2 text-error-500 hover:bg-error-50" @click="confirmError='';deleting=product"><Trash2 :size="17"/></button>
  </article>
  <p v-if="!products.length&&!loading" class="p-12 text-center text-sm text-gray-500">Товары не найдены.</p>
</div><PaginationControls v-if="pagination" :meta="pagination" :loading="loading" @change="load"/>
<BaseDialog :open="opened" labelledby="product-editor-title" describedby="product-editor-description" :close-disabled="saving" :suspended="Boolean(imageDeleting||groupDeleting)" overlay-class="z-50 p-3 sm:p-6" panel-class="mx-auto flex h-full max-w-6xl flex-col overflow-hidden rounded-xl bg-white shadow-xl" @close="close"><header class="flex justify-between border-b border-gray-200 px-5 py-4"><div><h2 id="product-editor-title" class="text-lg font-bold text-gray-900">{{editing?editing.name:'Новый товар'}}</h2><p id="product-editor-description" class="text-sm text-gray-500">Отдельная продаваемая позиция; объединение в модель выполняется позже.</p></div><button type="button" aria-label="Закрыть карточку товара" @click="close"><X :size="20"/></button></header><EditorSteps :steps="steps" :active="activeStep" :enabled="enabled" @select="activeStep=$event as Step"/><div class="flex-1 overflow-y-auto p-5 sm:p-6"><p v-if="error" role="alert" class="mb-4 rounded-lg bg-error-50 px-4 py-3 text-sm text-error-500">{{error}}</p><p v-if="success" role="status" class="mb-4 rounded-lg bg-success-50 px-4 py-3 text-sm text-success-500">{{success}}</p>
<form v-if="activeStep==='main'" class="grid gap-4 sm:grid-cols-2" @submit.prevent="saveMain"><label class="text-sm font-medium">Название<BaseInput :model-value="form.name" data-autofocus class="mt-1.5" required :placeholder="copiedFromName?'Введите новое название':''" :aria-describedby="copiedFromName?'copied-product-name-help':undefined" :aria-invalid="copiedNameError?'true':undefined" @update:model-value="v=>{form.name=v;copiedNameError='';if(!manuallyEditedSlug)form.slug=slugify(v)}"/><span v-if="copiedFromName" id="copied-product-name-help" class="mt-1.5 block text-xs text-warning-600">Укажите название, отличающееся от «{{copiedFromName}}».</span><span v-if="copiedNameError" class="mt-1.5 block text-xs text-error-500" role="alert">{{copiedNameError}}</span></label><label class="text-sm font-medium">URL (slug)<BaseInput v-model="form.slug" class="mt-1.5" required pattern="[a-z0-9]+(-[a-z0-9]+)*" @update:model-value="manuallyEditedSlug=true"/></label><label class="text-sm font-medium">Категория<BaseSelect v-model="selectedCategory" class="mt-1.5" :options="categoryOptions" placeholder="Выберите категорию" accessible-name="Категория" searchable/></label><label class="text-sm font-medium">Бренд<BaseSelect v-model="selectedBrand" class="mt-1.5" :options="brandOptions" accessible-name="Бренд" searchable/></label><label class="text-sm font-medium">SKU<BaseInput v-model="form.sku" class="mt-1.5" required pattern="[A-Za-z0-9][A-Za-z0-9._-]*"/></label><label class="text-sm font-medium">Артикул<BaseInput :model-value="form.article_number??''" class="mt-1.5" @update:model-value="v=>form.article_number=v||null"/></label><label class="text-sm font-medium">Штрихкод<BaseInput :model-value="form.barcode??''" class="mt-1.5" inputmode="numeric" pattern="([0-9]{8}|[0-9]{12,14})" @update:model-value="v=>form.barcode=v||null"/></label><label class="text-sm font-medium">Единица продажи<BaseSelect v-model="form.unit" class="mt-1.5" :options="units" accessible-name="Единица продажи"/></label><label class="text-sm font-medium">Цена<BaseInput v-model="form.price" class="mt-1.5" type="number" min="0" step="0.01" required/></label><label class="text-sm font-medium">Старая цена<BaseInput :model-value="form.old_price??''" class="mt-1.5" type="number" min="0" step="0.01" @update:model-value="v=>form.old_price=v||null"/></label><label class="text-sm font-medium">Остаток<BaseInput :model-value="String(form.stock_quantity)" class="mt-1.5" type="number" min="0" @update:model-value="v=>form.stock_quantity=Number(v)"/></label><label class="text-sm font-medium sm:col-span-2">Описание<BaseTextarea v-model="form.description" class="mt-1.5"/></label><p class="sm:col-span-2 rounded-lg bg-gray-50 px-3 py-2 text-sm text-gray-500">Новый товар сохранится как черновик. Публикация доступна на шаге «Проверка».</p><div class="sm:col-span-2 flex justify-end"><button class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving"><Save :size="17" class="mr-1 inline"/>{{saving?'Сохранение…':'Сохранить и продолжить'}}</button></div></form>
<form v-else-if="activeStep==='attributes'" @submit.prevent="saveAttributes"><h3 class="font-bold text-gray-900">Характеристики этой позиции</h3><p class="mt-1 text-sm text-gray-500">Они не наследуются другими вариантами модели. Черновик можно сохранить незаполненным.</p><div class="mt-5 grid gap-5 rounded-xl border border-gray-200 p-5 sm:grid-cols-2"><label v-for="a in attributes" :key="a.id" class="text-sm font-medium">{{a.name}}<span v-if="requiredIds.includes(a.id)" class="text-error-500"> *</span><AttributeValueField v-model="attributeValues[a.id]" class="mt-1.5" :attribute="a" :accessible-name="a.name" :required="form.is_active&&requiredIds.includes(a.id)"/></label></div><div class="mt-5 flex justify-end"><button class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white" :disabled="saving">{{saving?'Сохранение…':'Сохранить и продолжить'}}</button></div></form>
<div v-else-if="activeStep==='images'">
  <h3 class="font-bold text-gray-900">Фото этой позиции</h3>
  <form class="mt-5 rounded-xl border border-gray-200 bg-gray-25 p-4" @submit.prevent="upload">
    <p id="product-image-label" class="text-sm font-medium text-gray-700">Изображение</p>
    <input ref="imageInput" class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" tabindex="-1" aria-label="Файл изображения" @change="selectFile">
    <div class="mt-2 flex min-w-0 flex-col gap-2 sm:flex-row">
      <output class="min-h-11 min-w-0 flex-1 rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-700 shadow-input [overflow-wrap:anywhere]" aria-live="polite">{{selectedFile?.name??'Файл не выбран'}}</output>
      <button type="button" class="shrink-0 rounded-lg border border-gray-300 bg-white px-4 py-2.5 text-sm font-semibold text-gray-700 transition hover:bg-gray-50 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-primary-50 disabled:opacity-60" :disabled="saving" aria-describedby="product-image-file-help" @click="chooseFile">Выбрать файл</button>
    </div>
    <p id="product-image-file-help" class="mt-2 text-xs text-gray-500">Допустимые форматы: JPG, PNG или WebP. Максимальный размер — 10 МБ.</p>
    <button class="mt-4 inline-flex w-fit items-center gap-2 rounded-lg bg-primary-500 px-3 py-2 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60" :disabled="saving||!selectedFile"><ImagePlus :size="17"/>{{saving?'Загрузка…':'Загрузить'}}</button>
  </form>
  <p class="sr-only" role="status" aria-live="polite">{{imageStatus}}</p><p v-if="!images.length" class="mt-5 rounded-xl border border-dashed border-gray-300 px-5 py-10 text-center text-sm text-gray-500">Фотографий пока нет.</p>
  <div v-else class="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><article v-for="(image,index) in images" :key="image.id" class="overflow-hidden rounded-xl border border-gray-200"><img :src="image.url" :alt="image.alt||form.name" class="aspect-[4/3] w-full object-cover"><div class="space-y-3 p-3"><div class="flex flex-wrap items-center justify-between gap-2"><span v-if="index===0" class="text-xs font-semibold text-warning-600">Обложка</span><span class="break-all text-xs text-gray-500">{{image.alt}}</span></div><div class="flex flex-wrap gap-1"><button type="button" class="rounded-lg px-2 py-1 text-sm text-primary-600 disabled:opacity-40" :disabled="index===0||saving" :aria-label="`Переместить изображение ${index+1} выше`" @click="reorderImage(index,-1)">Выше</button><button type="button" class="rounded-lg px-2 py-1 text-sm text-primary-600 disabled:opacity-40" :disabled="index===images.length-1||saving" :aria-label="`Переместить изображение ${index+1} ниже`" @click="reorderImage(index,1)">Ниже</button><button type="button" class="rounded-lg px-2 py-1 text-sm font-semibold text-error-500 disabled:opacity-40" :disabled="saving" :aria-label="`Удалить изображение ${index+1}`" @click="confirmError='';imageDeleting=image">Удалить</button></div></div></article></div>
  <div class="mt-5 flex justify-end"><button type="button" class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving" @click="activeStep='group'">Продолжить</button></div>
</div>
<form v-else-if="activeStep==='group'" @submit.prevent="saveGroup">
  <h3 class="font-bold text-gray-900">Варианты модели</h3>
  <p class="text-sm text-gray-500">Объедините самостоятельные товары и выберите различающиеся характеристики.</p>
  <p v-if="copiedFromProduct&&groupForm.product_ids.includes(copiedFromProduct.id)" class="mt-3 break-words rounded-lg bg-primary-50 px-4 py-3 text-sm text-primary-600 [overflow-wrap:anywhere]" role="status">Исходный товар «{{copiedFromProduct.name}} · {{copiedFromProduct.sku}}» уже выбран. <template v-if="selectedGroupId">Новый товар подготовлен для добавления в существующую группу.</template><template v-else>Заполните параметры новой группы и выберите различающуюся характеристику.</template></p>
  <BaseSelect :model-value="selectedGroupId" class="mt-5 max-w-xl" :options="groupOptions" accessible-name="Группа вариантов" searchable @update:model-value="selectGroup"/>
  <div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium">Название группы<BaseInput v-model="groupForm.name" class="mt-1.5" required/></label><label class="text-sm font-medium">Уникальный код<BaseInput v-model="groupForm.code" class="mt-1.5" required/></label></div>
  <fieldset class="mt-5 rounded-xl border border-gray-300 p-4"><legend class="px-1 text-sm font-semibold">Различающиеся характеристики</legend><div class="grid gap-2 sm:grid-cols-2"><BaseCheckbox v-for="a in attributes.filter(item=>!['text','multiselect'].includes(item.type))" :key="a.id" v-model="groupForm.axis_attribute_ids" :value="a.id">{{a.name}}</BaseCheckbox></div><p v-if="groupErrors.axis_attribute_ids" role="alert" class="mt-2 text-sm text-error-500">{{groupErrors.axis_attribute_ids[0]}}</p></fieldset>
  <fieldset class="mt-5 rounded-xl border border-gray-300 p-4">
    <legend class="px-1 text-sm font-semibold">Товары группы</legend>
    <div class="mb-3 flex flex-col gap-2 sm:flex-row"><BaseInput v-model="groupSearch" class="min-w-0 flex-1" searchable placeholder="Название или SKU" aria-label="Поиск товаров для группы"/><button type="button" class="rounded-lg bg-gray-100 px-3 py-2 text-sm font-semibold disabled:opacity-60" :disabled="saving" @click="searchGroupProducts">{{saving?'Поиск…':'Найти'}}</button></div><p class="mb-3 text-xs text-gray-500">Первые 25 совпадений той же категории и бренда. Уточните поиск, если товара нет.</p>
    <div class="grid gap-2 sm:grid-cols-2"><BaseCheckbox v-for="p in groupProducts.filter(item=>item.category_id===editing?.category_id&&item.brand_id===editing?.brand_id)" :key="p.id" v-model="groupForm.product_ids" :value="p.id"><span class="flex min-w-0 items-center gap-2"><img v-if="p.primary_image" :src="p.primary_image.url" :alt="p.primary_image.alt||p.name" class="h-9 w-9 shrink-0 rounded object-cover"><span class="min-w-0 break-words [overflow-wrap:anywhere]">{{p.name}} · {{p.sku}}<span v-if="p.axis_values?.length" class="block text-xs text-gray-500">{{p.axis_values.map(value=>`${value.attribute?.name??'Характеристика'}: ${displayAttributeValue(value.attribute,value.value)}`).join(' · ')}}</span></span></span></BaseCheckbox></div>
    <p v-if="groupErrors.product_ids" role="alert" class="mt-2 text-sm text-error-500">{{groupErrors.product_ids[0]}}</p>
  </fieldset>
  <div class="mt-5 flex flex-wrap justify-end gap-3"><button v-if="selectedGroupId" type="button" class="rounded-lg px-4 py-2.5 text-sm font-semibold text-error-500 disabled:opacity-60" :disabled="saving" @click="confirmError='';groupDeleting=true">Удалить группу</button><button type="button" class="rounded-lg px-4 py-2.5 text-sm font-semibold text-gray-600 disabled:opacity-60" :disabled="saving" @click="activeStep='review'">Не объединять</button><button class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving">{{saving?'Сохранение…':'Сохранить группу'}}</button></div>
</form>
<div v-else id="product-review" class="space-y-5">
  <section id="product-review-summary" class="rounded-xl border border-gray-300 p-5" aria-labelledby="product-review-title">
    <header class="flex flex-wrap items-start justify-between gap-3"><div class="flex items-center gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-primary-50 text-primary-600"><Package :size="20"/></span><div><h3 id="product-review-title" class="font-bold text-gray-900">Информация о товаре</h3><p class="text-sm text-gray-500">Проверьте основные данные перед завершением.</p></div></div><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="form.is_active?'bg-success-50 text-success-500':'bg-gray-100 text-gray-500'">{{form.is_active?'Опубликован':'Черновик'}}</span></header>
    <dl class="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div class="rounded-lg bg-gray-25 px-4 py-3"><dt class="text-xs font-medium text-gray-500">SKU</dt><dd class="mt-1 break-words text-sm font-semibold text-gray-800 [overflow-wrap:anywhere]">{{form.sku}}</dd></div><div class="rounded-lg bg-gray-25 px-4 py-3"><dt class="text-xs font-medium text-gray-500">Цена и остаток</dt><dd class="mt-1 text-sm font-semibold text-gray-800">{{form.price}} ₽ · {{form.stock_quantity}} шт.</dd></div><div class="rounded-lg bg-gray-25 px-4 py-3"><dt class="text-xs font-medium text-gray-500">Фотографии</dt><dd class="mt-1 text-sm font-semibold text-gray-800">{{images.length}}</dd></div><div class="rounded-lg bg-gray-25 px-4 py-3"><dt class="text-xs font-medium text-gray-500">Группа вариантов</dt><dd class="mt-1 break-words text-sm font-semibold text-gray-800 [overflow-wrap:anywhere]">{{currentGroup?.name??'Не назначена'}}</dd></div></dl>
    <div v-if="requiredIds.some(id=>!hasValue(attributeValues[id]))" class="mt-4 rounded-lg bg-warning-50 p-3 text-sm text-warning-600">До публикации заполните обязательные характеристики: {{attributes.filter(a=>requiredIds.includes(a.id)&&!hasValue(attributeValues[a.id])).map(a=>a.name).join(', ')}}.</div><button v-if="!form.is_active" type="button" class="mt-4 rounded-lg bg-success-500 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-success-600 disabled:opacity-60" :disabled="saving" @click="publish">{{saving?'Публикация…':'Опубликовать товар'}}</button>
  </section>
  <section id="product-review-relations" class="rounded-xl border border-gray-300 p-5" aria-labelledby="product-relations-title">
    <div><h3 id="product-relations-title" class="font-bold text-gray-900">Сопутствующие товары</h3><p class="text-sm text-gray-500">Добавьте товары, которые стоит предложить покупателю вместе с этой позицией.</p></div>
    <div class="mt-4 flex flex-col gap-2 lg:flex-row"><BaseInput v-model="relationSearch" class="min-w-0 flex-1" searchable placeholder="Название или SKU" aria-label="Поиск сопутствующих товаров"/><button type="button" class="rounded-lg bg-gray-100 px-4 py-2.5 text-sm font-semibold text-gray-700 transition hover:bg-gray-200 disabled:opacity-60" :disabled="saving" @click="searchRelations">{{saving?'Поиск…':'Найти'}}</button><button type="button" class="inline-flex items-center justify-center gap-2 rounded-lg border border-primary-200 bg-primary-50 px-4 py-2.5 text-sm font-semibold text-primary-600 transition hover:bg-primary-100 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-primary-50 disabled:cursor-not-allowed disabled:opacity-60" :disabled="saving||!selectableCandidates.length" @click="addRelation"><Plus :size="17"/>Добавить</button></div>
    <p v-if="!relations.length" class="mt-4 rounded-lg bg-gray-50 p-4 text-sm text-gray-500">Сопутствующие товары не добавлены.</p><div v-for="(r,i) in relations" :key="i" class="mt-3 rounded-lg border border-gray-200 p-3"><div class="grid gap-2 sm:grid-cols-[1fr_160px_90px_auto]"><BaseSelect v-model="r.related_product_id" :options="[...selectableCandidates,...candidates.filter(p=>String(p.id)===r.related_product_id).map(p=>({value:String(p.id),label:`${p.name} · ${p.sku}`}))]" :accessible-name="`Сопутствующий товар ${i+1}`" searchable/><BaseSelect v-model="r.type" :options="relationTypes" :accessible-name="`Тип связи ${i+1}`"/><BaseInput v-model="r.sort_order" type="number" min="0" :aria-label="`Порядок связи ${i+1}`"/><button type="button" :aria-label="`Удалить связь ${i+1}`" class="rounded-lg p-2 text-error-500 transition hover:bg-error-50 disabled:opacity-40" :disabled="saving" @click="relations.splice(i,1)"><Trash2 :size="17"/></button></div><p v-if="relationErrors[i]" role="alert" class="mt-2 text-xs text-error-500">{{relationErrors[i]}}</p></div>
    <div class="mt-4 flex justify-end"><button type="button" class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-primary-600 disabled:opacity-60" :disabled="saving" @click="saveRelations">{{saving?'Сохранение…':'Сохранить рекомендации'}}</button></div>
  </section>
  <div class="flex justify-end"><button type="button" class="rounded-lg px-5 py-2.5 text-sm font-semibold text-gray-600 transition hover:bg-gray-50 disabled:opacity-60" :disabled="saving" @click="close">Закрыть</button></div>
</div></div></BaseDialog>
<BaseDialog :open="Boolean(deleting)" labelledby="delete-title" :close-disabled="saving" overlay-class="z-[60] grid place-items-center p-4" panel-class="w-full max-w-md rounded-xl bg-white p-6 shadow-xl" @close="confirmError='';deleting=null"><h2 id="delete-title" class="text-lg font-bold">Удалить товар?</h2><p v-if="confirmError" class="mt-3 text-sm text-error-500" role="alert">{{confirmError}}</p><p class="mt-2 text-sm text-gray-500">Будет удалена только эта продаваемая позиция.</p><div class="mt-6 flex justify-end gap-3"><button type="button" :disabled="saving" @click="confirmError='';deleting=null">Отмена</button><button type="button" :disabled="saving" class="rounded-lg bg-error-500 px-4 py-2 text-white disabled:opacity-60" @click="removeProduct">{{saving?'Удаление…':'Удалить'}}</button></div></BaseDialog></section>
<BaseDialog :open="Boolean(imageDeleting)" labelledby="delete-image-title" :close-disabled="saving" overlay-class="z-[70] grid place-items-center p-4" panel-class="w-full max-w-md rounded-xl bg-white p-6 shadow-xl" @close="confirmError='';imageDeleting=null"><h2 id="delete-image-title" class="text-lg font-bold">Удалить фотографию?</h2><p v-if="confirmError" class="mt-3 text-sm text-error-500" role="alert">{{confirmError}}</p><p class="mt-2 text-sm text-gray-500">Файл будет удалён без возможности восстановления.</p><div class="mt-6 flex justify-end gap-3"><button type="button" :disabled="saving" @click="confirmError='';imageDeleting=null">Отмена</button><button type="button" :disabled="saving" class="rounded-lg bg-error-500 px-4 py-2 text-white disabled:opacity-60" @click="removeImage">{{saving?'Удаление…':'Удалить'}}</button></div></BaseDialog>
<BaseDialog :open="groupDeleting" labelledby="delete-group-title" :close-disabled="saving" overlay-class="z-[70] grid place-items-center p-4" panel-class="w-full max-w-md rounded-xl bg-white p-6 shadow-xl" @close="confirmError='';groupDeleting=false"><h2 id="delete-group-title" class="text-lg font-bold">Удалить группу вариантов?</h2><p v-if="confirmError" class="mt-3 text-sm text-error-500" role="alert">{{confirmError}}</p><p class="mt-2 text-sm text-gray-500">Товары останутся самостоятельными позициями.</p><div class="mt-6 flex justify-end gap-3"><button type="button" :disabled="saving" @click="confirmError='';groupDeleting=false">Отмена</button><button type="button" :disabled="saving" class="rounded-lg bg-error-500 px-4 py-2 text-white disabled:opacity-60" @click="ungroup">{{saving?'Удаление…':'Удалить группу'}}</button></div></BaseDialog>
</template>
